{
  "grammar_topic": "Preposition",
  "sentence_structure": "S + V + Prep + [Relative Pronoun 'which' referring to time/event], with a preposition preceding 'which'.",
  "pattern": "Preposition + relative pronoun ('which') indicating time or sequence",
  "vocabulary": [
    {
      "word": "attendee",
      "meaning": "người tham dự",
      "part_of_speech": "noun"
    },
    {
      "word": "lecture",
      "meaning": "bài giảng, buổi thuyết trình",
      "part_of_speech": "noun"
    },
    {
      "word": "take place",
      "meaning": "diễn ra",
      "part_of_speech": "verb phrase"
    }
  ],
  "explanation": "Câu này kiểm tra việc sử dụng giới từ đi trước đại từ quan hệ 'which' để chỉ thời gian hoặc trình tự sự việc. Cụm 'after which' có nghĩa là 'sau khi [sự việc nào đó] kết hợp với mốc thời gian 6:00 P.M.', ngụ ý rằng sau thời điểm buổi thuyết trình diễn ra, người tham dự có thể đặt câu hỏi.",
  "distractor_analysis": {
    "A": "Đáp án 'across' (băng qua, ở bên kia) không phù hợp về mặt ngữ nghĩa và không kết hợp tự nhiên với cụm chỉ thời gian này.",
    "B": "Đáp án 'after' (sau) là chính xác, tạo thành cụm 'after which' (sau đó/sau mốc thời gian này) phù hợp hoàn toàn với ngữ cảnh thời gian và hoạt động đặt câu hỏi diễn ra sau buổi thuyết trình.",
    "C": "Đáp án 'inside' (bên trong) chỉ vị trí không gian, không phù hợp với mốc thời gian 6:00 P.M. và ngữ cảnh của câu.",
    "D": "Đáp án 'among' (giữa/trong số nhiều đối tượng) đòi hỏi một danh từ số nhiều theo sau, không thích hợp để đứng trước đại từ quan hệ 'which' chỉ mốc thời gian."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form (Adjective)",
  "sentence_structure": "S (The + [blank] + antique shop) + V (will close) + Prep (down) + Adv (next month).",
  "pattern": "Det + Adj + N",
  "vocabulary": [
    {
      "word": "antique shop",
      "meaning": "cửa hàng đồ cổ",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "close down",
      "meaning": "đóng cửa, ngừng hoạt động",
      "part_of_speech": "phrasal verb"
    },
    {
      "word": "last",
      "meaning": "còn lại, cuối cùng",
      "part_of_speech": "adjective"
    }
  ],
  "explanation": "Câu hỏi yêu cầu điền một từ vào vị trí trước danh từ 'antique shop' và sau mạo từ 'The'. Vị trí này cần một tính từ để bổ nghĩa cho danh từ 'antique shop'. Từ 'last' (dùng ở đây với nghĩa 'còn lại cuối cùng') đóng vai trò là tính từ đứng trước danh từ, hoàn toàn phù hợp về mặt ngữ pháp và ngữ nghĩa của câu.",
  "distractor_analysis": {
    "A": "Đáp án đúng. 'last' đóng vai trò là tính từ đứng trước cụm danh từ 'antique shop', tạo thành nghĩa hợp lý: cửa hàng đồ cổ cuối cùng ở Pepper Valley sẽ đóng cửa vào tháng tới.",
    "B": "Đáp án sai. 'lasts' là động từ chia ở ngôi thứ ba số ít thì hiện tại đơn, không thể đứng ở vị trí này vì câu đã có động từ chính là 'will close'.",
    "C": "Đáp án sai. 'lasted' là dạng quá khứ hoặc phân từ quá khứ của động từ 'last', không phù hợp để làm tính từ bổ nghĩa trực tiếp cho danh từ 'antique shop' trong cấu trúc này.",
    "D": "Đáp án sai. 'lasting' là hiện tại phân từ/tính từ mang nghĩa 'lâu dài', nhưng xét về ngữ cảnh và nghĩa của câu thì không phù hợp bằng tính từ 'last' (cuối cùng/còn lại).",
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Noun Collocation",
  "sentence_structure": "S (Merryville residents) + V (will receive) + Det (an) + Adj (online status) + N (_____), Prep-phrase (about the ongoing bridge construction project).",
  "pattern": "status update",
  "vocabulary": [
    {
      "word": "resident",
      "meaning": "cư dân",
      "part_of_speech": "noun"
    },
    {
      "word": "ongoing",
      "meaning": "đang diễn ra",
      "part_of_speech": "adjective"
    },
    {
      "word": "construction",
      "meaning": "sự xây dựng",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu hỏi kiểm tra khả năng kết hợp từ (collocation) trong ngữ cảnh thông báo dự án. Cụm từ thông dụng 'status update' có nghĩa là 'bản cập nhật trạng thái', hoàn toàn phù hợp với ngữ cảnh cư dân nhận được thông tin mới nhất về dự án xây dựng cầu đang diễn ra.",
  "distractor_analysis": {
    "A": "Đáp án chính xác. 'status update' là cụm danh từ quen thuộc chỉ việc cập nhật tình hình mới nhất của một dự án hoặc sự việc.",
    "B": "Đáp án không phù hợp. 'change' (sự thay đổi) có thể đứng sau 'status' trong một số ngữ cảnh rất hẹp, nhưng 'status update' mới là thuật ngữ chuẩn và tự nhiên trong tiếng Anh công sở khi nói về tiến độ dự án.",
    "C": "Đáp án sai về ngữ nghĩa. 'payment' (thanh toán) không tạo thành cụm từ hợp lý với 'status' trong ngữ cảnh thông báo về một dự án xây dựng cầu gửi đến cư dân.",
    "D": "Đáp án sai về ngữ nghĩa. 'request' (yêu cầu) không kết hợp phù hợp với 'status' để chỉ thông tin tiến độ dự án mà cư dân sẽ nhận được trực tuyến."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Pronouns (Possessive Determiners)",
  "sentence_structure": "Prep (As a result of) + [Possessive Determiner] + Noun (many years) + Participle Phrase (leading media organizations), S (Ms. Ayo) + V (was selected) + Prep Phrase (for the Dowel Journalism Prize).",
  "pattern": "As a result of + [possessive determiner (her/his/their/etc.)] + [noun] + [participle/gerund phrase]",
  "vocabulary": [
    {
      "word": "as a result of",
      "meaning": "kết quả của, do",
      "part_of_speech": "prepositional phrase"
    },
    {
      "word": "media organization",
      "meaning": "tổ chức truyền thông",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "select",
      "meaning": "lựa chọn, tuyển chọn",
      "part_of_speech": "verb"
    },
    {
      "word": "journalism",
      "meaning": "ngành báo chí",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Chỗ trống đứng trước cụm danh từ 'many years leading media organizations' và theo sau giới từ 'of' trong cụm 'As a result of'. Do đó, vị trí này cần một tính từ sở hữu (possessive determiner) để bổ nghĩa cho danh từ 'years'. Đáp án 'her' là tính từ sở hữu chính xác, tương ứng với chủ ngữ 'Ms. Ayo'.",
  "distractor_analysis": {
    "A": "Sai vì 'she' là đại từ nhân xưng chủ ngữ, không thể đứng trước cụm danh từ để làm từ hạn định sở hữu.",
    "B": "Đúng vì 'her' là tính từ sở hữu, đứng trước cụm danh từ 'many years' để chỉ khoảng thời gian nhiều năm làm việc của bà Ayo.",
    "C": "Sai vì 'hers' là đại từ sở hữu, dùng độc lập và không đứng trước một danh từ khác để làm từ hạn định.",
    "D": "Sai vì 'herself' là đại từ phản thân, thường dùng để nhấn mạnh hoặc khi chủ ngữ và tân ngữ cùng chỉ một đối tượng, không phù hợp với cấu trúc sở hữu này."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Noun Collocation and Vocabulary",
  "sentence_structure": "S (To stop the N of N) + V (do not open) + O (suspicious e-mails).",
  "pattern": "stop the spread of + [noun]",
  "vocabulary": [
    {
      "word": "spread",
      "meaning": "sự lây lan",
      "part_of_speech": "noun"
    },
    {
      "word": "suspicious",
      "meaning": "đáng ngờ",
      "part_of_speech": "adjective"
    },
    {
      "word": "virus",
      "meaning": "vi-rút máy tính",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này yêu cầu điền một danh từ phù hợp để kết hợp với danh từ 'computer viruses' theo ngữ cảnh của câu. Cụm từ 'the spread of computer viruses' (sự lây lan của vi-rút máy tính) là một collocation hoàn toàn chính xác về mặt ngữ nghĩa, phù hợp với lời khuyên 'do not open suspicious e-mails' (không mở các email đáng ngờ).",
  "distractor_analysis": {
    "A": "Đáp án 'break' không tạo thành cụm từ có nghĩa phù hợp với 'computer viruses' trong ngữ cảnh ngăn chặn sự lây lan.",
    "B": "Đáp án 'spread' là lựa chọn chính xác, tạo thành cụm từ 'spread of computer viruses' (sự lây lan của vi-rút máy tính), hoàn toàn phù hợp về mặt ý nghĩa và ngữ cảnh câu.",
    "C": "Đáp án 'balance' (sự cân bằng) không phù hợp về mặt ý nghĩa khi đi với 'computer viruses'.",
    "D": "Đáp án 'surface' (bề mặt) không liên quan đến ngữ cảnh phòng chống vi-rút máy tính qua email."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form (Adverb vs. Adjective)",
  "sentence_structure": "S (The hiring manager) + Adv (_____) + V (considered) + O (each applicant's résumé and qualifications).",
  "pattern": "Subject + Adverb + Verb + Object",
  "vocabulary": [
    {
      "word": "hiring manager",
      "meaning": "giám đốc tuyển dụng",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "consider",
      "meaning": "xem xét, cân nhắc",
      "part_of_speech": "verb"
    },
    {
      "word": "applicant",
      "meaning": "ứng viên",
      "part_of_speech": "noun"
    },
    {
      "word": "qualification",
      "meaning": "trình độ chuyên môn, năng lực",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu hỏi kiểm tra từ loại bổ nghĩa cho động từ. Trụ cột của vị trí trống nằm trước động từ chính 'considered'. Theo quy tắc ngữ pháp, trạng thái hoặc hành động được bổ nghĩa bởi trạng từ. Do đó, cần một trạng từ (carefully) để bổ nghĩa cho động từ 'considered', chỉ cách thức mà người quản lý tuyển dụng xem xét hồ sơ.",
  "distractor_analysis": {
    "A": "Sai vì 'caring' là tính từ hoặc phân từ mang nghĩa 'chu đáo, hay quan tâm', đứng ở vị trí này sẽ sai chức năng ngữ pháp vì không thể bổ nghĩa trực tiếp cho động từ chính theo cách đó.",
    "B": "Sai vì 'careful' là tính từ, dùng để bổ nghĩa cho danh từ chứ không thể đứng trước động từ 'considered' để bổ nghĩa cho hành động.",
    "C": "Đáp án chính xác vì 'carefully' là trạng từ, đứng trước động từ 'considered' để bổ nghĩa cho hành động xem xét hồ sơ một cách kỹ lưỡng.",
    "D": "Sai vì 'carefulness' là danh từ (sự cẩn thận), không phù hợp đứng ở vị trí bổ nghĩa cho động từ chính trong câu."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Coordinating Conjunction",
  "sentence_structure": "S + will leave + Prep + [will oversee + O], where the blank links two verb phrases sharing the same subject.",
  "pattern": "Verb 1 + and + Verb 2",
  "vocabulary": [
    {
      "word": "oversee",
      "meaning": "giám sát, quản lý",
      "part_of_speech": "verb"
    },
    {
      "word": "branch",
      "meaning": "chi nhánh",
      "part_of_speech": "noun"
    },
    {
      "word": "leave for",
      "meaning": "rời đi đến",
      "part_of_speech": "verb phrase"
    }
  ],
  "explanation": "Câu này yêu cầu một liên từ hoặc trạng từ nối tiếp hai hành động của cùng một chủ ngữ 'Mr. Sakamoto' (sẽ rời đi đến New Zealand và sẽ giám sát việc khai trương). Liên từ 'and' được dùng để nối hai động từ 'will leave' và 'will oversee' diễn ra liên tiếp hoặc song song.",
  "distractor_analysis": {
    "A": "because là liên từ chỉ nguyên nhân, không phù hợp về mặt ngữ nghĩa vì việc giám sát chi nhánh không phải là nguyên nhân của chuyến đi.",
    "B": "in addition là trạng từ (thường đi với 'to' hoặc đứng đầu mệnh đề với dấu phẩy), không dùng trực tiếp làm liên từ kết nối hai động từ trong cùng một vị trí này.",
    "C": "and là liên từ kết hợp chính xác để nối hai hành động 'will leave' và 'will oversee' do cùng một chủ ngữ thực hiện.",
    "D": "prior to là giới từ mang nghĩa 'trước khi', theo sau phải là danh từ hoặc danh động từ (gerund), không phù hợp để nối trực tiếp với động từ nguyên thể 'will oversee'."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Noun Collocation / Compound Noun",
  "sentence_structure": "S (Tarateer Pharmaceuticals) + V (is varying) + possessive adjective (its) + noun modifier (product) + blank (O) + infinitive clause (to include...).",
  "pattern": "product line",
  "vocabulary": [
    {
      "word": "vary",
      "meaning": "làm cho khác nhau, thay đổi, đa dạng hóa",
      "part_of_speech": "verb"
    },
    {
      "word": "product line",
      "meaning": "dòng sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "over-the-counter",
      "meaning": "bán không cần đơn của bác sĩ",
      "part_of_speech": "adjective"
    }
  ],
  "explanation": "Câu hỏi kiểm tra kiến thức về cụm danh từ (noun collocation). Cụm từ cố định 'product line' có nghĩa là 'dòng sản phẩm'. Trước chỗ trống là tính từ sở hữu 'its' và danh từ bổ nghĩa 'product', do đó vị trí này cần một danh từ chính đếm được số ít hoặc không đếm được để làm tân ngữ cho động từ 'is varying'. Danh từ 'line' là lựa chọn chính xác.",
  "distractor_analysis": {
    "A": "Sai vì cấu trúc 'to line' tạo thành động từ nguyên mẫu có 'to', không phù hợp làm tân ngữ trực tiếp cho động từ 'is varying' trong ngữ cảnh này.",
    "B": "Sai vì 'lining' là danh động từ hoặc phân từ hiện tại (V-ing), không tạo thành cụm từ chuẩn và không phù hợp với cấu trúc danh từ ghép của câu.",
    "C": "Sai vì 'lined' là quá khứ phân từ (V-ed/V3), không phải là danh từ thích hợp để tạo thành cụm từ chỉ dòng sản phẩm.",
    "D": "Đáp án chính xác. 'line' kết hợp với 'product' tạo thành cụm danh từ quen thuộc 'product line' (dòng sản phẩm), hoàn toàn phù hợp về mặt ngữ nghĩa và cấu trúc ngữ pháp của câu."
  },
  "difficulty": "medium"
}

